package com.adria.ai.web;import org.springframework.ai.chat.client.ChatClient;import org.springframework.ai.tool.ToolCallbackProvider;import org.springframework.web.bind.annotation.*;import java.util.Map;@RestController @RequestMapping("/api/chat") public class ChatController{private final ChatClient chat;private final ToolCallbackProvider tools;public ChatController(ChatClient.Builder builder,ToolCallbackProvider tools){this.chat=builder.build();this.tools=tools;}@PostMapping public Map<String,String> chat(@RequestBody Map<String,String> body){String message=body.get("message");if(message==null||message.isBlank())throw new IllegalArgumentException("message obligatoire");String answer=chat.prompt().system("Tu es un assistant bancaire. N'invente jamais de données. Utilise les outils disponibles pour consulter les comptes et transactions. Demande confirmation avant toute opération financière.").user(message).toolCallbacks(tools).call().content();return Map.of("response",answer==null?"Aucune réponse":answer);}}